        outer = json.loads(body)
    except ValueError as error:
        raise ValueError(
            f"bit map history body is not valid JSON: {error}"
        ) from error
    if not isinstance(outer, list) or len(outer) != 3:
        raise ValueError(
            "bit map history body must be an array of exactly start,"
            " updates and end"
